#include <websocketpp/config/asio_no_tls.hpp>
#include <websocketpp/server.hpp>
#include <syslog.h>
#include <cstdio>
#include <string>
#include <map>
#include <mutex>
#include <memory>
#include <functional>

typedef websocketpp::server<websocketpp::config::asio> ws_server;

class AuditLogger {
public:
    enum class Level { INFO, WARN, ERROR };

    static AuditLogger& instance() {
        static AuditLogger logger;
        return logger;
    }

    void init(const std::string& facility_name) {
        openlog(facility_name.c_str(), LOG_PID | LOG_NDELAY, LOG_LOCAL0);
        initialized_ = true;
    }

    template<typename... Args>
    void log(Level level, const char* component, const std::string& message, Args&&... args) {
        if (!initialized_) return;

        int priority = level_to_priority(level);
        std::string formatted = format_component(component, message);

        // Write to syslog with structured format
        write_entry(priority, formatted, std::forward<Args>(args)...);
    }

private:
    bool initialized_ = false;
    std::mutex mtx_;

    AuditLogger() = default;

    int level_to_priority(Level level) {
        switch(level) {
            case Level::INFO: return LOG_INFO;
            case Level::WARN: return LOG_WARNING;
            case Level::ERROR: return LOG_ERR;
            default: return LOG_DEBUG;
        }
    }

    std::string format_component(const char* component, const std::string& message) {
        // Prefix with component tag for log aggregation
        return std::string("[") + component + "] " + message;
    }

    // Base case: no additional args, message is the format itself
    void write_entry(int priority, const std::string& entry) {
        std::lock_guard<std::mutex> lock(mtx_);
        syslog(priority, "%s", entry.c_str());
    }

    // Variadic case: forward format string and args to syslog
    template<typename... Args>
    void write_entry(int priority, const std::string& fmt, Args&&... args) {
        std::lock_guard<std::mutex> lock(mtx_);
        syslog(priority, fmt.c_str(), std::forward<Args>(args)...);
    }
};

class SessionManager {
public:
    struct Session {
        std::string username;
        std::string remote_addr;
        int message_count = 0;
    };

    void register_session(websocketpp::connection_hdl hdl, const std::string& addr) {
        std::lock_guard<std::mutex> lock(mtx_);
        sessions_[hdl.lock().get()] = {"anonymous", addr, 0};
    }

    void authenticate(websocketpp::connection_hdl hdl, const std::string& username) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = sessions_.find(hdl.lock().get());
        if (it != sessions_.end()) {
            it->second.username = username;
        }
    }

    Session* get_session(websocketpp::connection_hdl hdl) {
        auto it = sessions_.find(hdl.lock().get());
        if (it != sessions_.end()) return &it->second;
        return nullptr;
    }

    void remove_session(websocketpp::connection_hdl hdl) {
        std::lock_guard<std::mutex> lock(mtx_);
        sessions_.erase(hdl.lock().get());
    }

private:
    std::mutex mtx_;
    std::map<void*, Session> sessions_;
};

class ChatServer {
public:
    ChatServer() {
        AuditLogger::instance().init("ws-chat");

        server_.init_asio();
        server_.set_open_handler(std::bind(&ChatServer::on_open, this, std::placeholders::_1));
        server_.set_close_handler(std::bind(&ChatServer::on_close, this, std::placeholders::_1));
        server_.set_message_handler(std::bind(&ChatServer::on_message, this,
            std::placeholders::_1, std::placeholders::_2));
    }

    void run(uint16_t port) {
        server_.listen(port);
        server_.start_accept();
        AuditLogger::instance().log(AuditLogger::Level::INFO, "server",
            "WebSocket server started on port %d", port);
        server_.run();
    }

private:
    ws_server server_;
    SessionManager sessions_;

    void on_open(websocketpp::connection_hdl hdl) {
        auto con = server_.get_con_from_hdl(hdl);
        std::string addr = con->get_remote_endpoint();
        sessions_.register_session(hdl, addr);

        AuditLogger::instance().log(AuditLogger::Level::INFO, "connect",
            "New connection from %s", addr.c_str());
    }

    void on_close(websocketpp::connection_hdl hdl) {
        auto* session = sessions_.get_session(hdl);
        if (session) {
            AuditLogger::instance().log(AuditLogger::Level::INFO, "disconnect",
                "User disconnected: %s", session->username.c_str());
        }
        sessions_.remove_session(hdl);
    }

    void on_message(websocketpp::connection_hdl hdl, ws_server::message_ptr msg) {
        auto* session = sessions_.get_session(hdl);
        if (!session) return;

        std::string payload = msg->get_payload();
        session->message_count++;

        // Handle authentication command
        if (payload.substr(0, 5) == "/auth") {
            std::string username = payload.substr(6);
            if (validate_username(username)) {
                sessions_.authenticate(hdl, username);
                audit_auth_event(session, username);
                server_.send(hdl, "AUTH_OK", websocketpp::frame::opcode::text);
            } else {
                server_.send(hdl, "AUTH_FAIL", websocketpp::frame::opcode::text);
            }
            return;
        }

        // Handle status command - log the user's custom status message
        if (payload.substr(0, 7) == "/status") {
            std::string status_msg = payload.substr(8);
            audit_status_change(session, status_msg);
            server_.send(hdl, "STATUS_SET", websocketpp::frame::opcode::text);
            return;
        }

        // Regular message broadcast
        broadcast(session->username + ": " + payload);
    }

    bool validate_username(const std::string& username) {
        if (username.empty() || username.length() > 32) return false;
        for (char c : username) {
            if (!isalnum(c) && c != '_' && c != '-') return false;
        }
        return true;
    }

    void audit_auth_event(SessionManager::Session* session, const std::string& username) {
        AuditLogger::instance().log(AuditLogger::Level::INFO, "auth",
            "Authentication successful for user: %s from %s",
            username.c_str(), session->remote_addr.c_str());
    }

    void audit_status_change(SessionManager::Session* session, const std::string& status) {
        // Log the status change event with user context
        std::string log_entry = "User " + session->username + " status: " + status;
        AuditLogger::instance().log(AuditLogger::Level::INFO, "status", log_entry);
    }

    void broadcast(const std::string& message) {
        // Simplified broadcast - in production would iterate connections
        AuditLogger::instance().log(AuditLogger::Level::INFO, "broadcast",
            "Message broadcast: %s", message.c_str());
    }
};

int main() {
    ChatServer server;
    server.run(9002);
    return 0;
}
